mapper.select:
SELECT COUNT(*) FROM FMSOWN.TB_SCM_COM_CD C LEFT JOIN FMSOWN.TB_SCM_SUBSYS S ON S.SUBSYS_CD = C.SUBSYS_CD LEFT JOIN FMSOWN.TB_SCM_COM_CD_MLNG M ON M.COM_CD_ID = C.COM_CD_ID AND M.MLNG_LANG_CD = NVL(#{mlngLangCd}, 'KO') WHERE 1 = 1
AND C.SUBSYS_CD = #{subsysCd}
AND C.COM_CD_ID LIKE '%' || #{comCdId} || '%'
AND M.COM_CD_NM LIKE '%' || #{comCdNm} || '%'
AND C.DEL_YN = #{delYn}

SELECT COUNT(*)
FROM FMSOWN.TB_SCM_COM_CD
WHERE COM_CD_ID = #{comCdId}

mapper.update:
UPDATE FMSOWN.TB_SCM_COM_CD
SET DEL_YN = 'Y'
WHERE COM_CD_ID = #{comCdId}

BEGIN
	UPDATE FMSOWN.TB_SCM_COM_CD
	SET COM_CD_LEN = #{comCdLen}
		, SUBSYS_CD = #{subsysCd}
		, SYS_COM_CD_YN = NVL(#{sysComCdYn}, 'N')
		, DEL_YN = NVL(#{delYn}, 'N')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId};
	UPDATE FMSOWN.TB_SCM_COM_CD_MLNG
	SET COM_CD_NM = NVL(#{comCdNmKo}, ' ')
		, COM_CD_EXPLN = NVL(#{comCdExplnKo}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND MLNG_LANG_CD = 'KO';
	UPDATE FMSOWN.TB_SCM_COM_CD_MLNG
	SET COM_CD_NM = NVL(#{comCdNmEn}, ' ')
		, COM_CD_EXPLN = NVL(#{comCdExplnEn}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND MLNG_LANG_CD = 'EN';
	UPDATE FMSOWN.TB_SCM_COM_CD_MLNG
	SET COM_CD_NM = NVL(#{comCdNmZh}, ' ')
		, COM_CD_EXPLN = NVL(#{comCdExplnZh}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND MLNG_LANG_CD = 'ZH';
END;

mapper.select:
SELECT D.COM_CD_ID , M.COM_CD_NM , D.DTL_CD , DM.DTL_CD_NM , D.SORT_SEQ , D.DEL_YN , D.CRT_DT , D.UPDT_DT FROM FMSOWN.TB_SCM_COM_CD_DTL D LEFT JOIN FMSOWN.TB_SCM_COM_CD_MLNG M ON M.COM_CD_ID = D.COM_CD_ID AND M.MLNG_LANG_CD = NVL(#{mlngLangCd}, 'KO') LEFT JOIN FMSOWN.TB_SCM_COM_CD_DTL_MLNG DM ON DM.COM_CD_ID = D.COM_CD_ID AND DM.DTL_CD = D.DTL_CD AND DM.MLNG_LANG_CD = NVL(#{mlngLangCd}, 'KO') WHERE 1 = 1
AND D.COM_CD_ID = #{comCdId}
AND D.DEL_YN = #{delYn}
ORDER BY D.COM_CD_ID, D.SORT_SEQ, D.DTL_CD
OFFSET #{startNo} ROWS FETCH NEXT #{listCount} ROWS ONLY

SELECT COUNT(*) FROM FMSOWN.TB_SCM_COM_CD_DTL D LEFT JOIN FMSOWN.TB_SCM_COM_CD_MLNG M ON M.COM_CD_ID = D.COM_CD_ID AND M.MLNG_LANG_CD = NVL(#{mlngLangCd}, 'KO') LEFT JOIN FMSOWN.TB_SCM_COM_CD_DTL_MLNG DM ON DM.COM_CD_ID = D.COM_CD_ID AND DM.DTL_CD = D.DTL_CD AND DM.MLNG_LANG_CD = NVL(#{mlngLangCd}, 'KO') WHERE 1 = 1
AND D.COM_CD_ID = #{comCdId}
AND D.DEL_YN = #{delYn}

SELECT COUNT(*)
FROM FMSOWN.TB_SCM_COM_CD_DTL
WHERE COM_CD_ID = #{comCdId}
	AND DTL_CD = #{dtlCd}

mapper.update:
UPDATE FMSOWN.TB_SCM_COM_CD_DTL
SET DEL_YN = 'Y'
WHERE COM_CD_ID = #{comCdId}
	AND DTL_CD = #{dtlCd}

BEGIN
	UPDATE FMSOWN.TB_SCM_COM_CD_DTL
	SET SORT_SEQ = #{sortSeq}
		, DEL_YN = NVL(#{delYn}, 'N')
		, APLCN_BGNG_YND = NVL(#{aplcnBgngYnd}, '19000101')
		, APLEN_END_YMD = NVL(#{aplcnEndYmd}, '99991231')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId}
		AND DTL_CD = #{dtlCd};
	UPDATE FMSOWN.TB_SCM_COM_CD_DTL_MLNG
	SET DTL_CD_NM = NVL(#{dtlCdNmKo}, ' ')
		, COM_CD_EXPLN = NVL(#{dtlCdExplnKo}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND DTL_CD = #{dtlCd} AND MLNG_LANG_CD = 'KO';
	UPDATE FMSOWN.TB_SCM_COM_CD_DTL_MLNG
	SET DTL_CD_NM = NVL(#{dtlCdNmEn}, ' ')
		, COM_CD_EXPLN = NVL(#{dtlCdExplnEn}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND DTL_CD = #{dtlCd} AND MLNG_LANG_CD = 'EN';
	UPDATE FMSOWN.TB_SCM_COM_CD_DTL_MLNG
	SET DTL_CD_NM = NVL(#{dtlCdNmZh}, ' ')
		, COM_CD_EXPLN = NVL(#{dtlCdExplnZh}, ' ')
		, UPDT_USER_ID = #{updtUserId}
		, UPDT_DT = SYSDATE
	WHERE COM_CD_ID = #{comCdId} AND DTL_CD = #{dtlCd} AND MLNG_LANG_CD = 'ZH';
END;
